    if (w[1].second != (EHeroAbility)ABILITY_B || w[2].second != (EHeroAbility)ABILITY_C) ok = 0;
    if (!ok) { std::printf("005f7cd0_TEST FAIL\n"); return 1; }
    std::printf("005f7cd0_TEST PASS\n");
